// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, uint256 v) public {
        // Deploy an adversarial callee whose transferFrom always reverts.
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);

        bool ok = true;
        try c.transfer(from, address(reverter), tos, v) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference C propagates the failed external call and reverts; buggy M ignores it and returns true.
        // The property: a transfer whose underlying transferFrom fails must NOT report success.
        assertTrue(!ok);
    }
}

contract Reverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert();
    }
}
